begin;
create function public.update_budget_item(p_item_id uuid,p_descricao text,p_quantidade integer,p_valor_unitario_centavos integer) returns public.orcamento_itens language plpgsql security definer set search_path='' as $$ declare a uuid:=auth.uid();r public.orcamento_itens%rowtype;begin select * into r from public.orcamento_itens where id=p_item_id for update;if not found or (not public.can_manage_financial() and not public.can_access_own_budget(r.orcamento_id)) then raise exception 'Acesso negado.' using errcode='42501';end if;if exists(select 1 from public.orcamentos where id=r.orcamento_id and status not in('rascunho','enviado')) then raise exception 'Orcamento encerrado.' using errcode='23514';end if;update public.orcamento_itens set descricao=btrim(p_descricao),quantidade=p_quantidade,valor_unitario_centavos=p_valor_unitario_centavos,updated_by=a where id=r.id returning * into r;perform public.refresh_budget_total(r.orcamento_id);insert into public.auditoria(usuario_id,evento,entidade,entidade_id,dados)values(a,'orcamento_item_atualizado','orcamento_itens',r.id,jsonb_build_object('orcamento_id',r.orcamento_id));return r;end;$$;
create function public.remove_budget_item(p_item_id uuid) returns public.orcamento_itens language plpgsql security definer set search_path='' as $$ declare a uuid:=auth.uid();r public.orcamento_itens%rowtype;begin select * into r from public.orcamento_itens where id=p_item_id for update;if not found or(not public.can_manage_financial()and not public.can_access_own_budget(r.orcamento_id))then raise exception 'Acesso negado.'using errcode='42501';end if;update public.orcamento_itens set status_ativo=false,updated_by=a where id=r.id returning * into r;perform public.refresh_budget_total(r.orcamento_id);insert into public.auditoria(usuario_id,evento,entidade,entidade_id,dados)values(a,'orcamento_item_removido','orcamento_itens',r.id,jsonb_build_object('orcamento_id',r.orcamento_id));return r;end;$$;
create function public.update_validity_item(p_item_id uuid,p_descricao text,p_data_validade date,p_lote_codigo text,p_responsavel_id uuid,p_observacao_administrativa text) returns public.controle_validade language plpgsql security definer set search_path='' as $$ declare a uuid:=auth.uid();r public.controle_validade%rowtype;begin if not public.can_manage_financial()then raise exception 'Acesso negado.'using errcode='42501';end if;update public.controle_validade set descricao=btrim(p_descricao),data_validade=p_data_validade,lote_codigo=nullif(btrim(p_lote_codigo),''),responsavel_id=p_responsavel_id,observacao_administrativa=nullif(btrim(p_observacao_administrativa),''),updated_by=a where id=p_item_id and status_operacional='ativo' returning * into r;if not found then raise exception 'Item inacessivel.'using errcode='23514';end if;insert into public.auditoria(usuario_id,evento,entidade,entidade_id,dados)values(a,'validade_item_atualizado','controle_validade',r.id,jsonb_build_object('campos_alterados',jsonb_build_array('descricao','data_validade','lote_codigo','responsavel_id')));return r;end;$$;
alter table public.auditoria drop constraint if exists auditoria_evento_check;alter table public.auditoria add constraint auditoria_evento_check check(evento in('usuario_convidado','convite_aceito','usuario_ativado','usuario_desativado','perfil_alterado','acao_administrativa_negada','senha_redefinida','configuracao_acesso_alterada','paciente_criado','paciente_atualizado','paciente_inativado','paciente_reativado','alertas_clinicos_atualizados','agendamento_criado','agendamento_remarcado','agendamento_alterado','agendamento_confirmado','agendamento_cancelado','agendamento_falta_registrada','agendamento_atendido','atendimento_iniciado','atendimento_criado_direto','atendimento_alterado','atendimento_finalizado','procedimento_criado','procedimento_atualizado','retorno_criado','retorno_atualizado','retorno_agendado','retorno_concluido','retorno_cancelado','tarefa_criada','tarefa_atualizada','tarefa_concluida','tarefa_cancelada','documento_criado','arquivo_enviado','arquivo_removido','pagamento_criado','pagamento_atualizado','pagamento_cancelado','orcamento_criado','orcamento_item_criado','orcamento_status_alterado','validade_item_criado','validade_item_utilizado','validade_item_descartado','orcamento_item_atualizado','orcamento_item_removido','validade_item_atualizado'));
revoke execute on function public.update_budget_item(uuid,text,integer,integer),public.remove_budget_item(uuid),public.update_validity_item(uuid,text,date,text,uuid,text) from public,anon;grant execute on function public.update_budget_item(uuid,text,integer,integer),public.remove_budget_item(uuid),public.update_validity_item(uuid,text,date,text,uuid,text) to authenticated;
commit;
